"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[1027],{91020(e){e.exports=JSON.parse('{"tag":{"label":"approximation-algorithms","permalink":"/azeon/p-vs-np/tags/approximation-algorithms","allTagsPath":"/azeon/p-vs-np/tags","count":3,"items":[{"id":"heuristics/approximating-vertex-cover","title":"Approximating Vertex Cover","description":"Back to the cameras from Posts 11 and 16. Pick any unwatched road and put cameras on both ends. Repeat. That\'s the whole algorithm, it\'s never worse than twice the best, and the proof fits in four lines.","permalink":"/azeon/p-vs-np/heuristics/approximating-vertex-cover"},{"id":"heuristics/approximation-algorithms","title":"Approximation Algorithms","description":"You can\'t find the best answer quickly, but you can sometimes prove your quick answer is never worse than twice the best, without ever knowing what the best is. Some problems allow amazing guarantees. Others allow none at all.","permalink":"/azeon/p-vs-np/heuristics/approximation-algorithms"},{"id":"heuristics/tsp-and-the-triangle-inequality","title":"TSP and the Triangle Inequality","description":"General TSP can\'t be approximated at all. Add one sensible rule, that going direct is never longer than taking a detour, and a spanning tree gives a tour within twice the best. Christofides\' 1976 trick gets that to 1.5.","permalink":"/azeon/p-vs-np/heuristics/tsp-and-the-triangle-inequality"}],"unlisted":false}}')}}]);